class IndependentDailyStrategies(QCAlgorithm):

    def Initialize(self):
        self.SetStartDate(2006, 1, 3)
        self.SetEndDate(2015, 12, 31)
        self.SetCash(1_000_000)

        self.symbols = {}
        for ticker in ["SPY", "AAPL", "IBM", "BAC", "AIG"]:
            self.symbols[ticker] = self.AddEquity(ticker, Resolution.Daily).Symbol

        self.spy = self.symbols["SPY"]
        self.aapl = self.symbols["AAPL"]

        self.spy_closes = RollingWindow[float](201)
        self.aapl_closes = RollingWindow[float](16)

        self.aapl_rsi = self.RSI(
            self.aapl,
            14,
            MovingAverageType.Wilders,
            Resolution.Daily
        )

        self.strategy_a_shares = 0
        self.strategy_b_shares = 0
        self.aapl_red_streak = 0

    def OnData(self, data: Slice):
        # Every subscribed ticker must have today's daily bar.
        bars = {}
        for ticker, symbol in self.symbols.items():
            if symbol not in data.Bars:
                return
            bars[ticker] = data.Bars[symbol]

        spy_close = bars["SPY"].Close
        aapl_close = bars["AAPL"].Close

        # Market-state quantities are updated continuously on valid complete days.
        previous_aapl_close = self.aapl_closes[0] if self.aapl_closes.Count > 0 else None

        if previous_aapl_close is not None:
            if aapl_close < previous_aapl_close:
                self.aapl_red_streak += 1
            else:
                self.aapl_red_streak = 0

        self.spy_closes.Add(spy_close)
        self.aapl_closes.Add(aapl_close)

        # Do not trade until every required indicator/window is fully formed.
        if self.spy_closes.Count < 201 or not self.aapl_rsi.IsReady:
            return

        # Sells are evaluated before buys.
        if self.strategy_a_shares > 0:
            spy_sma_50_today = sum(self.spy_closes[i] for i in range(50)) / 50.0
            spy_sma_50_yesterday = sum(self.spy_closes[i] for i in range(1, 51)) / 50.0
            spy_close_yesterday = self.spy_closes[1]

            if spy_close_yesterday >= spy_sma_50_yesterday and spy_close < spy_sma_50_today:
                self.MarketOrder(self.spy, -self.strategy_a_shares)
                self.strategy_a_shares = 0

        if self.strategy_b_shares > 0 and self.aapl_rsi.Current.Value > 60:
            self.MarketOrder(self.aapl, -self.strategy_b_shares)
            self.strategy_b_shares = 0

        if self.strategy_a_shares == 0:
            spy_sma_200_today = sum(self.spy_closes[i] for i in range(200)) / 200.0
            spy_sma_200_yesterday = sum(self.spy_closes[i] for i in range(1, 201)) / 200.0
            spy_close_yesterday = self.spy_closes[1]

            if spy_close_yesterday <= spy_sma_200_yesterday and spy_close > spy_sma_200_today:
                shares = int((self.Portfolio.TotalPortfolioValue * 0.40) / spy_close)
                if shares > 0:
                    self.MarketOrder(self.spy, shares)
                    self.strategy_a_shares = shares

        if self.strategy_b_shares == 0 and self.aapl_red_streak >= 3:
            if self.Portfolio.Cash >= 20_000:
                shares = int(20_000 / aapl_close)
                if shares > 0:
                    self.MarketOrder(self.aapl, shares)
                    self.strategy_b_shares = shares
