        if self.strategy_a_lot == 0 and spy_ready:
            crossed_above_200 = (
                self.previous_spy_close <= self.previous_spy_sma_200
                and spy_bar.Close > self.spy_sma_200.Current.Value
            )
            if crossed_above_200:
                shares = int((self.Portfolio.TotalPortfolioValue * 0.40) // spy_bar.Close)
                if shares > 0:
