from AlgorithmImports import *
from collections import deque


class IndependentDailyStrategies(QCAlgorithm):
    def Initialize(self):
        self.SetStartDate(2006, 1, 3)
        self.SetEndDate(2015, 12, 31)
        self.SetCash(1_000_000)

        self.symbols = {}
        for ticker in ["SPY", "AAPL", "IBM", "BAC", "AIG"]:
            self.symbols[ticker] = self.AddEquity(ticker, Resolution.Daily).Symbol

        self.closes = {ticker: deque(maxlen=201) for ticker in self.symbols}
        self.red_streak = 0

        self.rsi_period = 14
        self.rsi_changes = 0
        self.rsi_seed_gains = []
        self.rsi_seed_losses = []
        self.rsi_avg_gain = None
        self.rsi_avg_loss = None
        self.aapl_rsi = None

        self.strategy_a_shares = 0
        self.strategy_b_shares = 0

    def OnData(self, data: Slice):
        # Market-state quantities are updated whenever an individual bar exists.
        for ticker, symbol in self.symbols.items():
            if not data.Bars.ContainsKey(symbol):
                continue

            close = data.Bars[symbol].Close
            history = self.closes[ticker]

            if ticker == "AAPL" and len(history) > 0:
                previous_close = history[-1]

                if close < previous_close:
